def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(x == v for row in grid for x in row))

    def run(row):
        vals = [(c, row[c]) for c in range(w) if row[c] != bg]
        if not vals:
            return None
        color = max(set(v for _, v in vals), key=lambda v: sum(x == v for _, x in vals))
        cols = [c for c, v in vals if v == color]
        # edge bar is the longest contiguous run of the non-background bar color
        runs = []
        for c in cols:
            if not runs or c > runs[-1][-1] + 1:
                runs.append([c])
            else:
                runs[-1].append(c)
        return max(runs, key=len), color

    top, bottom = run(grid[0]), run(grid[-1])
    if not top or not bottom:
        return [r[:] for r in grid]
    topcols, topcolor = top
    botcols, botcolor = bottom
    ts, bs = min(topcols), min(botcols)
    out = [r[:] for r in grid]
    barcolors = {topcolor, botcolor}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or v in barcolors:
                continue
            # Each interior colored marker launches a vertical ray on its own side,
            # and a translated ray in the other bar's aligned column.
            if c in topcols:
                dc = bs - ts
                for rr in range(1, r):
                    if out[rr][c] == bg:
                        out[rr][c] = v
                cc = c + dc
                if 0 <= cc < w:
                    for rr in range(h):
                        if grid[rr][cc] == bg:
