def transform(grid):
    h, w = len(grid), len(grid[0])
    flat = [x for row in grid for x in row]
    bg = max(set(flat), key=flat.count)

    def edge_bar(row):
        runs = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color = row[c]
            start = c
            while c < w and row[c] == color:
                c += 1
            runs.append((c - start, start, c - 1, color))
        return max(runs) if runs else None

    top = edge_bar(grid[0])
    bottom = edge_bar(grid[-1])
    if top is None or bottom is None:
        return [row[:] for row in grid]
    _, ts, te, tc = top
    _, bs, be, bc = bottom
    out = [row[:] for row in grid]

    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == tc or color == bc:
                continue
            if ts <= c <= te:
                i = c - ts
                if i > be - bs:
                    continue
                pair_c = bs + i
                # Continue the ray from this marker to its own (top) bar.
                for rr in range(1, r):
                    if grid[rr][c] == bg:
                        out[rr][c] = color
                # Its matching column runs from the far edge to the opposite bar.
                for rr in range(h):
                    if grid[rr][pair_c] == bg:
                        out[rr][pair_c] = color
            elif bs <= c <= be:
                i = c - bs
                if i > te - ts:
                    continue
                pair_c = ts + i
                # Continue the ray from this marker to its own (bottom) bar.
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] == bg:
                        out[rr][c] = color
                # Matching column runs from the far edge to the opposite bar.
                for rr in range(h):
                    if grid[rr][pair_c] == bg:
                        out[rr][pair_c] = color
            out[r][c] = 4
    return out
